/**
 * What OpportunityDTO promises about itself, checked here as a courtesy.
 *
 * The server enforces these when the row is written - that is what
 * makes them true. This is so a form can say what is wrong before
 * the request, in the domain's own words.
 *
 * @returns the promises this value breaks, empty when it keeps them
 */
export function violations(opportunity: OpportunityDTO | null | undefined): string[] {
    const broken: string[] = [];
    if (opportunity == null) return broken;
    if (opportunity.amount != null && Number(opportunity.amount) < 0) {
        broken.push('amount must be at least 0');
    }
    if (opportunity.probability != null && opportunity.probability < 0) {
        broken.push('probability must be at least 0');
    }
    if (opportunity.probability != null && opportunity.probability > 100) {
        broken.push('probability must be at most 100');
    }
    return broken;
}

/** Whether OpportunityDTO keeps every promise it makes. */
export function isValid(opportunity: OpportunityDTO | null | undefined): boolean {
    return violations(opportunity).length === 0;
}
